import {browserAIRequest} from './ai-client-context.mjs';import {aiFacts,localAssistance} from './ai-context.mjs';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={explain:'Explain this shipment',transporter:'Draft transporter message',documents:'Summarize document gaps'};
const reasonText={disabled:'Live AI is switched off.',key_missing:'The server has no saved API key.',feature_disabled:'This AI feature is switched off.',usage_limit:'The local usage limit was reached.',busy:'Another AI request is in progress.',provider_quota:'The API project has no available quota or credits.',provider_auth:'The API credential was rejected.',provider_access:'The API project does not have access.',provider_model_unavailable:'The configured model is unavailable to this API project.',provider_rate_limit:'The provider rate limit was reached.',provider_error:'The provider could not complete the request.',timeout:'The live request timed out.',validation_failed:'The AI result failed factual-output checks.',invalid_json:'The AI returned unusable output.',incomplete:'The AI result was incomplete.',refused:'The model declined the request.',network_or_validation_error:'The live connection or output check failed.',local_requested:'You selected local assistance.'};
export async function openCopilot({state,options,modal,onReview,getCurrentState}){
 let status=null,response=null,request=null,sourceJSON=null,csrf=null,baseText='',reviewed=false;
 const first=browserAIRequest(state,options),facts=aiFacts(first);
 modal(titles[options.feature],`<div class="copilot-tag"><span>AI COPILOT</span><b id="ai-provider">Checking local connection…</b></div><div class="help">Operator assistance only. Generate AI sends the displayed minimized shipment facts to OpenAI. File bytes, driver details and contacts are excluded. No message is sent to a transporter and no operational approval is granted.</div><details class="ai-source"><summary>Source facts used for this request</summary><div>${facts.map(f=>`<p><b>${e(f.label)}:</b> ${e(f.value)}</p>`).join('')}</div></details>${options.feature==='documents'?'<div class="field" style="margin-top:14px"><label for="ai-document-excerpt">Optional extracted document text · sample data only</label><textarea id="ai-document-excerpt" maxlength="8000" placeholder="Paste an extract if you want AI to suggest content discrepancies. No PDF/OCR extraction is performed here."></textarea><small>Untrusted text is advisory input. Existing document gates cannot be overridden by AI.</small></div>':''}<div class="buttons" style="margin:16px 0"><button class="btn primary" id="ai-generate">Generate live AI</button><button class="btn" id="ai-local">Use local rules / template</button></div><div id="ai-message" role="status" class="small muted">Choose live AI or a clearly labeled local fallback.</div><div id="ai-result" hidden><div class="line"></div><h3 id="ai-result-title"></h3><div id="ai-output"></div><label class="small muted" for="ai-reviewed-text" style="display:block;margin:16px 0 7px">Editable operator draft / review notes</label><textarea id="ai-reviewed-text" class="receipt" style="width:100%;min-height:180px" maxlength="12000"></textarea><div class="buttons" style="margin-top:13px"><button class="btn primary" id="ai-accept">Accept reviewed draft</button><button class="btn" id="ai-reject">Reject suggestion</button></div><p class="small muted" style="margin-top:12px">Acceptance saves a local review record only. This is not dispatch, financial approval or an external send.</p></div>`);
 const byId=id=>document.getElementById(id);const alive=()=>!!byId('ai-provider')&&document.getElementById('modal')?.open;const getRequest=()=>browserAIRequest(getCurrentState(),{...options,documentText:byId('ai-document-excerpt')?.value||''});
 try{const res=await fetch('/api/ai/status',{credentials:'same-origin'});if(!res.ok)throw Error('Status unavailable');status=await res.json();if(!alive())return;csrf=status.csrf;byId('ai-provider').textContent=status.enabled?'API configured; availability checked on request · '+status.model:'Local fallback available · live AI not enabled';byId('ai-generate').disabled=!status.enabled||!status.features[options.feature];}catch{if(!alive())return;byId('ai-provider').textContent='Local-only mode · AI server unavailable';byId('ai-generate').disabled=true;}
 async function generate(mode){
  byId('ai-generate').disabled=true;byId('ai-local').disabled=true;byId('ai-result').hidden=true;byId('ai-message').textContent=mode==='local'?'Preparing local assistance…':'Generating from the displayed source facts…';reviewed=false;
  try{request=getRequest();sourceJSON=JSON.stringify(request);if(csrf){const res=await fetch('/api/ai/generate',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-LML-CSRF':csrf},body:JSON.stringify({...request,mode})});if(!res.ok){const error=await res.json().catch(()=>({}));throw Error(error.error||'Request failed');}response=await res.json();}
   else response={provider:'local-rules',reason:'server_unavailable',result:localAssistance(request),facts:aiFacts(request),requestId:null,promptVersion:'local-only'};
   if(!alive())return;const live=response.provider==='openai',result=response.result;byId('ai-message').textContent=live?`Live AI · ${response.model} · operator review required`:`Local rules / template · ${reasonText[response.reason]||'The live connection is unavailable.'}`;byId('ai-result-title').textContent=result.title;byId('ai-output').innerHTML=`<p style="margin:12px 0;font-size:12px;line-height:1.8">${e(result.summary)}</p><ul class="ai-findings">${result.actions.map(x=>`<li>${e(x)}</li>`).join('')}</ul><div class="help"><b>Missing information / review:</b><br>${result.missing_information.map(e).join('<br>')}</div><p class="small muted">Source references: ${result.fact_ids.map(e).join(', ')}</p>`;
   const text=[result.summary,...result.actions.map(x=>'• '+x)].join('\n\n');const sourceBlock=options.feature==='transporter'?'\n\nSOURCE DETAILS — verify before sharing\n'+response.facts.filter(f=>['shipment','principal','origin','destination','departure','truck','quantity','weight','volume','freight'].includes(f.id)).map(f=>f.label+': '+f.value).join('\n'):'';baseText=text+sourceBlock;byId('ai-reviewed-text').value=baseText;byId('ai-result').hidden=false;byId('ai-accept').disabled=false;byId('ai-reject').disabled=false;
  }catch(error){if(!alive())return;byId('ai-message').textContent=error.message+' Manual operations remain available.';}
  finally{if(!alive())return;byId('ai-generate').disabled=!status?.enabled||!status?.features[options.feature];byId('ai-local').disabled=false;}
 }
 async function review(outcome){if(reviewed||!response)return;try{if(JSON.stringify(getRequest())!==sourceJSON)throw Error('Source facts or document text changed. Regenerate before review.');const content=byId('ai-reviewed-text').value;const actual=outcome==='accepted'&&content!==baseText?'edited':outcome;if(response.requestId&&csrf){const res=await fetch('/api/ai/feedback',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-LML-CSRF':csrf},body:JSON.stringify({requestId:response.requestId,fingerprint:response.fingerprint,outcome:actual,editLength:content.length})});if(!res.ok)throw Error('Review logging failed. Retry after refreshing the connection.');}
  if(!alive())return;onReview({feature:options.feature,provider:response.provider,requestId:response.requestId,fingerprint:response.fingerprint||null,promptVersion:response.promptVersion,outcome:actual,content:actual==='rejected'?'':content});reviewed=true;if(!alive())return;byId('ai-message').textContent='Review recorded: '+actual+'. No message sent or operational action performed.';byId('ai-accept').disabled=true;byId('ai-reject').disabled=true;
 }catch(error){if(alive())byId('ai-message').textContent=error.message;}}
 byId('ai-generate').onclick=()=>generate('live');byId('ai-local').onclick=()=>generate('local');byId('ai-accept').onclick=()=>review('accepted');byId('ai-reject').onclick=()=>review('rejected');
}
